#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

# Shared with scripts/cloudflare-setup.sh (git-ignored; nothing in it is secret)
ENV_FILE=".cloudflare-wizard.env"

# ── Helpers for this wizard ───────────────────────────────────────────────
FAILS=0
pass() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { printf '  %s✗ %s%s\n' "$YELLOW" "$1" "$RESET"; FAILS=$((FAILS + 1)); }

status_of()   { curl -s -o /dev/null -w '%{http_code}' --max-time 15 "$1" || echo 000; }
location_of() { curl -s -o /dev/null -w '%{redirect_url}' --max-time 15 "$1" || true; }
body_has()    { curl -s --max-time 15 "$1" | grep -q "$2"; }

# check_site BASE runs the same checks as #29's `wrangler dev` verification.
# SLASH_STATUS is the expected trailing-slash redirect status (307 from Workers
# itself, 308 once the redirect rule in stage 4 exists).
check_site() {
  local base="$1" slash_status="${2:-}"; FAILS=0
  [[ "$(status_of "$base/")" == 200 ]] && body_has "$base/" "Bloomington-Normal Developers" \
    && pass "home page loads" || fail "home page didn't load from $base/"
  [[ "$(status_of "$base/events/37")" == 200 ]] \
    && pass "an Event page loads (/events/37)" || fail "/events/37 didn't return 200"
  [[ "$(location_of "$base/events/37/")" == "$base/events/37" ]] \
    && pass "/events/37/ redirects to /events/37" || fail "/events/37/ didn't redirect to /events/37"
  if [[ -n "$slash_status" ]]; then
    [[ "$(status_of "$base/events/37/")" == "$slash_status" ]] \
      && pass "  ...with a $slash_status" || fail "  ...but not with a $slash_status"
  fi
  [[ "$(status_of "$base/nope")" == 404 ]] && body_has "$base/nope" "404 - Page Not Found" \
    && pass "unknown paths get the custom 404 page" || fail "/nope didn't return the custom 404"
  [[ "$(status_of "$base/sitemap-index.xml")" == 200 ]] \
    && pass "sitemap is served" || fail "/sitemap-index.xml didn't return 200"
  (( FAILS == 0 ))
}

# retry_checks "what" CMD...: run a check until it passes or the human gives up
retry_checks() {
  local what="$1"; shift
  until "$@"; do
    printf '\n'
    confirm "Some checks failed. Re-run them?" || { SKIPPED+=("$what"); return 1; }
    printf '\n'
  done
}

ns_of() { dig +short NS blono.dev @1.1.1.1 | sort | tr '\n' ' '; }

banner "blono.dev → Cloudflare, part 2: cutover (issue #30)"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Preflight"
say "Part 2 switches blono.dev from Vercel to the Cloudflare Worker."
printf '\n'
for cmd in curl dig git gh; do
  command -v "$cmd" >/dev/null 2>&1 && pass "$cmd is installed" || { fail "$cmd is missing"; exit 1; }
done
[[ -f wrangler.jsonc ]] || { fail "run this from the repo root (wrangler.jsonc not found)"; exit 1; }
if [[ "$(ns_of)" == *ns.cloudflare.com* ]]; then
  pass "blono.dev's DNS is on Cloudflare: $(ns_of)"
else
  fail "blono.dev's nameservers aren't Cloudflare's yet ($(ns_of))."
  say "Finish scripts/cloudflare-setup.sh first."
  exit 1
fi
git fetch -q origin main
if git cat-file -e origin/main:wrangler.jsonc 2>/dev/null; then
  pass "origin/main contains the Astro site"
else
  fail "origin/main is still the Next.js site. Merge the migration (#31) first."
  exit 1
fi
ask WORKERS_DEV_URL "The Worker's workers.dev URL:"
WORKERS_DEV_URL="${WORKERS_DEV_URL%/}"
write_env WORKERS_DEV_URL "$WORKERS_DEV_URL"
pause "Press Enter to start"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Deploy main as production"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Open the ${BOLD}blono-dev${RESET} Worker → Settings → Build → Branch control."
step "Set Production branch to ${BOLD}main${RESET} → Save."
step "Open Deployments/Builds. If there's no successful production build of main"
step "  since the switch, retry the latest main build."
printf '\n'
if confirm "No way to retry it in the dashboard? Push an empty commit to main to trigger one?"; then
  if git diff --quiet && git diff --cached --quiet; then
    branch=$(git rev-parse --abbrev-ref HEAD)
    git switch -q main && git pull -q --ff-only origin main \
      && git commit -q --allow-empty -m "chore: trigger Cloudflare production deploy" \
      && git push -q origin main && pass "pushed an empty commit to main"
    git switch -q "$branch"
  else
    warn "Your working tree has uncommitted changes, so I won't switch branches."
    warn "Commit or stash them, or retry the build in the dashboard."
  fi
fi
pause "Press Enter once the main build has deployed successfully"
printf '\n'
say "Checking $WORKERS_DEV_URL ..."
retry_checks "workers.dev checks after deploying main" check_site "$WORKERS_DEV_URL" || true
pause

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Cut over: point blono.dev at the Worker"
say "This is the switch. There may be a few minutes of errors while Cloudflare"
say "issues the HTTPS certificates."
note "Rollback: delete the two Custom Domains and re-add the DNS records"
note "  A blono.dev 76.76.21.21 and CNAME www cname.vercel-dns.com (DNS only)."
note "  Vercel keeps serving until you retire it in stage 6."
printf '\n'
confirm "Cut blono.dev over to Cloudflare now?" || { SKIPPED+=("the cutover (stages 3-6): re-run this wizard"); finish; exit 0; }
open_url "https://dash.cloudflare.com/?to=/:account/:zone/dns/records"
step "Pick the blono.dev zone if asked. In DNS → Records, ${BOLD}delete${RESET}:"
note "    A      blono.dev   76.76.21.21"
note "    CNAME  www         cname.vercel-dns.com"
step "Then open Workers & Pages → ${BOLD}blono-dev${RESET} → Settings → Domains & Routes → Add →"
step "  Custom domain → ${BOLD}www.blono.dev${RESET} → Add."
step "Add a second Custom domain: ${BOLD}blono.dev${RESET}."
pause "Press Enter once both custom domains are added"
printf '\n'
say "Waiting for www.blono.dev to serve the new site (checking every 20s, up to 15 min)..."
for _ in $(seq 1 45); do
  # Vercel never served a sitemap, so this only passes once the Worker answers
  [[ "$(status_of https://www.blono.dev/sitemap-index.xml)" == 200 ]] && break
  printf '.'; sleep 20
done
printf '\n'
retry_checks "www.blono.dev checks after cutover" check_site "https://www.blono.dev" || true
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Redirect rules: blono.dev → www, and drop trailing slashes"
open_url "https://dash.cloudflare.com/?to=/:account/:zone/rules/overview"
step "Pick blono.dev if asked. Create a ${BOLD}Redirect Rule${RESET} named 'blono.dev to www':"
note "    If incoming requests match: wildcard pattern"
note "      Request URL:  https://blono.dev/*"
note "    Then: Target URL  https://www.blono.dev/\${1}   Status 301   Preserve query string"
note "  (Cloudflare's 'Redirect from root to WWW' template sets this up.)"
step "Create a second Redirect Rule named 'Drop trailing slash':"
note "    Request URL:  https://*/*/"
note "    Then: Target URL  https://\${1}/\${2}   Status 308   Preserve query string"
note "  (This matches the old site's 308; Workers alone answers with a 307.)"
step "Deploy both rules."
pause "Press Enter once both rules are deployed"
printf '\n'
FAILS=0
[[ "$(status_of https://blono.dev/events/37)" == 301 && "$(location_of https://blono.dev/events/37)" == "https://www.blono.dev/events/37" ]] \
  && pass "blono.dev/events/37 → 301 → www.blono.dev/events/37" \
  || fail "blono.dev/events/37 didn't 301 to www.blono.dev/events/37"
[[ "$(status_of https://blono.dev/)" == 301 ]] \
  && pass "blono.dev/ → 301 → www" || fail "blono.dev/ didn't 301"
retry_checks "redirect rule checks" check_site "https://www.blono.dev" 308 || true
pause

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Check an Event's link preview (closes #27)"
open_url "https://www.opengraph.xyz/url/https%3A%2F%2Fwww.blono.dev%2Fevents%2F37"
step "The preview should show 'Developer Happy Hour | Bloomington-Normal Developers',"
step "  the November details, and the Keg Grove fall photo."
printf '\n'
if confirm "Does the preview show the Event's title and photo?"; then
  if confirm "Close #27 with a comment saying so?"; then
    gh issue close 27 --comment "Verified after the Cloudflare cutover: https://www.blono.dev/events/37 shows the Event's title, details and photo in a link-preview checker (opengraph.xyz)." \
      && pass "closed #27"
  fi
else
  SKIPPED+=("link preview for /events/37 (check the og:image tag and that the image URL loads)")
fi
pause

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Retire Vercel"
say "Cloudflare now serves blono.dev, so Vercel's copy is no longer reachable by domain."
open_url "https://vercel.com/dashboard"
step "Open the blono.dev project → Settings → Domains."
step "Remove ${BOLD}blono.dev${RESET} and ${BOLD}www.blono.dev${RESET}. If Vercel offers to change DNS, decline:"
step "  DNS now lives at Cloudflare."
pause "Press Enter once the domains are removed"
printf '\n'
note "Keeping the project for a week or so leaves an easy rollback. Delete it with"
note "Settings → Advanced → Delete Project when you're confident."
if confirm "Delete the Vercel project now?"; then
  step "Settings → Advanced → Delete Project, and type the project name to confirm."
  pause "Press Enter once it's deleted"
else
  SKIPPED+=("delete the Vercel project when you're confident (Settings → Advanced → Delete Project)")
fi
printf '\n'
if confirm "Close #30 with a comment summarising the cutover?"; then
  gh issue close 30 --comment "Cutover done: blono.dev DNS is on Cloudflare, Workers Builds deploys main, www.blono.dev and blono.dev are Custom Domains on the blono-dev Worker, blono.dev redirects to www (301), trailing slashes redirect with a 308, and the domains are removed from Vercel." \
    && pass "closed #30"
fi

finish
say "blono.dev is live on Cloudflare. You can delete ${ENV_FILE} once you're done."
printf '\n'
}

run_wizard "$@"; exit
